    printf("Enter three sides: ");
    scanf("%f %f %f", &a, &b, &c);
    float s = (a + b + c) / 2;
    float area = sqrt(s * (s - a) * (s - b) * (s - c));
    printf("Area of scalene"
           " triangle = %f\n", area);
    return 0;
}

