c:
#include <stdio.h>
int main() {
    // for loop
    for (int i=0; i<10; i++)
        printf("Bangladesh\n");
    // while loop
    int j=0;
    while (j<10) { printf("Bangladesh\n"); j++; }
    // do-while loop
    int k=0;
    do { printf("Bangladesh\n"); k++; }
    while (k<10);
    return 0;
}

