#include <stdio.h>

int main() {
    int num, count = 0;
    printf("Enter any positive number: ");
    scanf("%d", &num);
    if (num <= 1) {
        printf("Not Prime Number");
        return 0;
    }
    for (int i = 2; i < num; i++) {
        if (num % i == 0) {
            count++;
            break;
        }
    }
    if (count == 0)
        printf("Prime Number");
    else
        printf("Not Prime Number");
    return 0;
}

