int main() {
    int num, temp, r, sum = 0, f;
    printf("Enter a number: ");
    scanf("%d", &num);
    temp = num;
    while (temp != 0) {
        r = temp % 10;
        f = 1;
        for (int i = 1; i <= r; i++)
            f = f * i;
        sum = sum + f;
        temp = temp / 10;
    }
    if (sum == num)
        printf("Strong number\n");
    else
        printf("Not strong number\n");
    return 0;
}

