    int row, col, n;
    printf("Enter a value of n: ");
    scanf("%d", &n);
    for (row = 1; row <= n; row++) {
        for (col = 1; col <= row; col++)
            printf("%d ", col%2);
        printf("\n");
    }
    for (row = n - 1; row >= 1; row--) {
        for (col = 1; col <= row; col++)
            printf("%d ", col%2);
        printf("\n");
    }
    return 0;
}

