using namespace std;
int main() {
    int row, col, count = 0, n;
    cout << "Enter a value of n: ";
    cin >> n;
    for (row = 1; row <= n; row++) {
        for (col = 1; col <= row; col++) {
            cout << count++ << " ";
        }
        cout << endl;
    }
    return 0;
}

