c:
#include <stdio.h>

int fact(int n) {
    if (n <= 1) return 1;
    else return n * fact(n - 1);
}

int main() {
    int number, result;
    printf("Enter a positive number: ");
    scanf("%d", &number);
    result = fact(number);
    printf("%d", result);
    return 0;
}

