c:
#include <stdio.h>

int power(int x, int y) {
    if (y == 0) return 1;
    else return (x * power(x, y-1));
}

int main() {
    int b, p, c;
    printf("Enter Base and Power: ");
    scanf("%d %d", &b, &p);
    c = power(b, p);
    printf("%d", c);
    return 0;
}

