#include <stdio.h>

int main() {
    int num[100], n, i;
    printf("How many numbers: ");
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &num[i]);
    int max = num[0];
    for (i = 0; i < n; i++)
        if (max < num[i]) max = num[i];
    printf("%d\n", max);
    return 0;
}

